package com.hfr.packet.builder;
import com.hfr.builder.BuilderDepotService;import com.hfr.schematic.*;import com.hfr.tileentity.machine.TileEntityMachineBuilder;import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.tileentity.TileEntity;import net.minecraft.util.ChatComponentText;
/** Bounded normalized import bridge. SchematicPayload revalidates dimensions, palette and byte limits server-side. */
public class BuilderSchematicPacket implements IMessage {private int dimension,x,y,z,originX,originY,originZ,rotation;private boolean mirror;private SchematicPayload payload;public BuilderSchematicPacket(){}public BuilderSchematicPacket(TileEntityMachineBuilder d,Schematic s,int x,int y,int z,int rotation,boolean mirror){dimension=d.getWorldObj().provider.dimensionId;this.x=d.xCoord;this.y=d.yCoord;this.z=d.zCoord;originX=x;originY=y;originZ=z;this.rotation=rotation;this.mirror=mirror;payload=new SchematicPayload(s);}public void fromBytes(ByteBuf b){dimension=b.readInt();x=b.readInt();y=b.readInt();z=b.readInt();originX=b.readInt();originY=b.readInt();originZ=b.readInt();rotation=b.readByte();mirror=b.readBoolean();payload=new SchematicPayload(b);}public void toBytes(ByteBuf b){b.writeInt(dimension);b.writeInt(x);b.writeInt(y);b.writeInt(z);b.writeInt(originX);b.writeInt(originY);b.writeInt(originZ);b.writeByte(rotation);b.writeBoolean(mirror);payload.toBytes(b);}public static class Handler implements IMessageHandler<BuilderSchematicPacket,IMessage>{public IMessage onMessage(BuilderSchematicPacket m,MessageContext c){EntityPlayerMP p=c.getServerHandler().playerEntity;if(p==null||p.dimension!=m.dimension||p.getDistanceSq(m.x+.5,m.y+.5,m.z+.5)>64)return null;TileEntity te=p.worldObj.getTileEntity(m.x,m.y,m.z);if(!(te instanceof TileEntityMachineBuilder))return null;TileEntityMachineBuilder d=(TileEntityMachineBuilder)te;String error;try{error=BuilderDepotService.accept(p,d,m.payload.deserialize(),m.originX,m.originY,m.originZ,m.rotation,m.mirror);}catch(RuntimeException e){error="Malformed schematic upload.";}if(error!=null)p.addChatMessage(new ChatComponentText(error));return BuilderDepotSnapshotPacket.create(d);}}}
